entries[36954] = { ["name"] = "Dimensionszerfetzer: Area 52", ["text"] = "Wirken in 3 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Urfeuer (2), Der Größere (2), Eine Hand voll Teufelseisenbolzen (4), Khoriumkraftkern\nDimensionszerfetzer: Area 52\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nBenutzen: Zerreißt die Dimensionsschranken und transportiert Euch nach Area 52 im Nethersturm. Manchmal können technische Probleme auftreten, aber das ist ja das Spannende bei der Gobliningenieurskunst! (4 Std. Abklingzeit)" }
entries[36955] = { ["name"] = "Extrem sicherer Transporter: Toshleys Station", ["text"] = "Wirken in 3 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Urluft (2), Teufelsstahlstabilisator (2), Eine Hand voll Teufelseisenbolzen (4), Khoriumkraftkern\nExtrem sicherer Transporter: Toshleys Station\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gnomeningenieur\nBenutzen: Transportiert Euch sicher zu Toshleys Station beim Schergrat! Es gibt nichts, worüber man sich bei der Benutzung dieses Geräts sorgen müsste! Dank der gnomischen Ingenieurskunst kommt jeder schnell und zuverlässig ans Ziel! (4 Std. Abklingzeit)" }
